class Starship {
  name;
  #fuelLevel;

  constructor(name, initialFuel) {
    this.name = name;
    this.#fuelLevel = Math.max(0, initialFuel);
  }

  getFuelLevel() {
    return this.#fuelLevel;
  }

  refuel(amount) {
    if (amount <= 0 || typeof amount !== 'number') {
      console.log("Refuel amount must be a positive number.");
      return;
    }
    this.#fuelLevel += amount;
    console.log(`${this.name} refueled by ${amount}. Current fuel: ${this.#fuelLevel}`);
  }

  travel(distance) {
    if (distance <= 0 || typeof distance !== 'number') {
      console.log("Travel distance must be a positive number.");
      return false;
    }
    if (this.#fuelLevel < distance) {
      console.log(`${this.name}: Not enough fuel to travel ${distance} units! Current fuel: ${this.#fuelLevel}`);
      return false;
    }
    this.#fuelLevel -= distance;
    console.log(`${this.name} traveled ${distance} units. Remaining fuel: ${this.#fuelLevel}`);
    return true;
  }
}

